#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "resident/domains/politics/politics_projection_detail.hpp"
// 有限显式NPC意图不预造委任、本人接受或原Authority；未知人物和重复一次目标在作者阶段拒绝。
#include "political_governance_agency_intents.hpp"
#include "resident/domains/local_economy/local_economy_codec_detail.hpp"
#include "resident/domains/politics/takeover/politics_takeover_payload_guard.hpp"
#include <set>
namespace hanmo::resident::dynamic_economy_codec {
// 三位各自策略和本人选择均为作者明示，不从关系好感或原Office推断同意。
template<class A>void record(A& a,PoliticalGovernanceAgencyIntent& v){a("id",v.id);a("agency_policy_id",v.agency_policy_id);a("principal_actor_id",v.principal_actor_id);a("delegate_actor_id",v.delegate_actor_id);a("executor_actor_id",v.executor_actor_id);a("principal_director_policy_id",v.principal_director_policy_id);a("delegate_director_policy_id",v.delegate_director_policy_id);a("executor_director_policy_id",v.executor_director_policy_id);a("delegate_accepts",v.delegate_accepts);a("executor_accepts",v.executor_accepts);}
// 本目录仅在独立新模块中序列化；旧Director/agency1没有空尾。
template<class A>void record(A& a,PoliticalGovernanceAgencyIntentCatalog& v){a("version",v.version);a("intents",v.intents);}
}
namespace hanmo::resident {namespace {
Status shape(const PoliticalGovernanceAgencyIntentCatalog& c){if(c.version!=1||c.intents.empty()||c.intents.size()>64)return common_failure("InvalidGovernanceAgencyIntentCatalog");std::set<StableId> policies;
 for(const auto& row:c.intents.rows()){const auto& i=row.second;if(row.first!=i.id||i.principal_actor_id==i.delegate_actor_id||i.principal_actor_id==i.executor_actor_id||i.delegate_actor_id==i.executor_actor_id||(!i.delegate_accepts&&i.executor_accepts)||!policies.insert(i.agency_policy_id).second)return common_failure("InvalidGovernanceAgencyIntent",row.first);for(const auto* id:{&i.id,&i.agency_policy_id,&i.principal_actor_id,&i.delegate_actor_id,&i.executor_actor_id,&i.principal_director_policy_id,&i.delegate_director_policy_id,&i.executor_director_policy_id})if(id->empty()||id->size()>4096)return common_failure("InvalidGovernanceAgencyIntent",row.first);}return common_success();}
}
Outcome<PoliticalGovernanceAgencyIntentCatalog> decode_political_governance_agency_intents(const BoundaryValue& value){auto unique=validate_political_takeover_payload(value);if(!unique.ok)return {false,{},unique.error};try{PoliticalGovernanceAgencyIntentCatalog out;dynamic_economy_codec::decode(value,out,"/political_governance_agency_intents");auto s=shape(out);return s.ok?Outcome<PoliticalGovernanceAgencyIntentCatalog>{true,std::move(out),{}}:Outcome<PoliticalGovernanceAgencyIntentCatalog>{false,{},s.error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
// 原目录字段借读出口，沿同一record供值与shape发射，不生成业务状态。
Status emit_political_governance_agency_intents_fields(ProjectionWriter& writer,const PoliticalGovernanceAgencyIntentCatalog& c){
 try{return dynamic_economy_codec::emit_fields(writer,c);}
 catch(const boundary::DecodeFailure& e){return writer.reject(e.error.original.code,e.error.original.path);}
}
BoundaryValue encode_political_governance_agency_intents(const PoliticalGovernanceAgencyIntentCatalog& c){return politics_projection_detail::encode_fields(c,emit_political_governance_agency_intents_fields);}
// raw作者两组严格同启，正式Director仍须用同一目录完整校验原人员和策略引用。
Outcome<std::optional<PoliticalGovernanceAgencyIntentCatalog>> decode_political_governance_agency_intent_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){const auto* dynamic=scenario.find("dynamic_world");const auto* agency=dynamic?dynamic->find(political_governance_agency_domain):nullptr;const auto* director=dynamic?dynamic->find("director"):nullptr;const auto* group=director?director->find("governance_agency_intents"):nullptr;if(!group)return {true,std::nullopt,{}};try{if(!agency||boundary::integer(boundary::field(*agency,"version","/political_governance_agencies"),"/version")!=2||std::find(caps.begin(),caps.end(),"political_governance_agencies_v2")==caps.end()||std::find(caps.begin(),caps.end(),"political_governance_agency_intents_v1")==caps.end())return {false,{},common_failure("GovernanceAgencyIntentVersionPairRequired").error};auto decoded=decode_political_governance_agency_intents(*group);return decoded.ok?Outcome<std::optional<PoliticalGovernanceAgencyIntentCatalog>>{true,std::move(decoded.value),{}}:Outcome<std::optional<PoliticalGovernanceAgencyIntentCatalog>>{false,{},decoded.error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
// 不读取现任者：作者原职与原人物不可变；后来更替使实际预览暂停，不倒改目录或旧意愿。
Status validate_political_governance_agency_intents(const PoliticalGovernanceAgencyIntentCatalog& c,const CommonCatalog& common,const PoliticsCatalog& politics,const OrganizationCatalog& organizations,const PoliticalGovernanceAgencyCatalog& agencies){auto s=shape(c);if(!s.ok)return s;if(agencies.version!=2||!politics.enabled||!organizations.enabled)return common_failure("GovernanceAgencyIntentVersionPairRequired");for(const auto& row:c.intents.rows()){const auto& i=row.second;const auto* p=agencies.policies.find(i.agency_policy_id);const auto* j=p?politics.jurisdictions.find(p->jurisdiction_id):nullptr;const auto* office=p?organizations.offices.find(p->office_id):nullptr;if(!p||!j||!office||j->office_id!=office->id||office->organization_id!=j->political_organization_id||office->holder_actor_id!=std::optional<StableId>{i.principal_actor_id}||office->deputy_actor_id)return common_failure("GovernanceAgencyIntentOriginalOfficeRequired",i.id);for(const auto* actor:{&i.principal_actor_id,&i.delegate_actor_id,&i.executor_actor_id})if(std::find(common.actor_ids.begin(),common.actor_ids.end(),*actor)==common.actor_ids.end())return common_failure("GovernanceAgencyIntentActorRequired",*actor);}return common_success();}
// 原永久业务事实还要核此源所对应的真实非玩家控制前界；本函数本身不能授权写账。
Status validate_political_governance_agency_authored_origin(const PoliticalGovernanceAgencyIntentCatalog& c,const PoliticalGovernanceAgencyAuthoredOrigin& o,const StableId& actor,const StableId& kind){auto s=shape(c);if(!s.ok)return s;const auto* i=c.intents.find(o.intent_id);if(!i||o.actor_id!=actor)return common_failure("GovernanceAgencyIntentOriginMismatch",o.intent_id);if(o.step==PoliticalGovernanceAgencyAuthoredStep::offer)return actor==i->principal_actor_id&&o.director_policy_id==i->principal_director_policy_id&&kind==political_governance_agency_offer_command?common_success():common_failure("GovernanceAgencyIntentOriginMismatch",o.intent_id);if(o.step==PoliticalGovernanceAgencyAuthoredStep::answer)return actor==i->delegate_actor_id&&o.director_policy_id==i->delegate_director_policy_id&&kind==political_governance_agency_answer_command?common_success():common_failure("GovernanceAgencyIntentOriginMismatch",o.intent_id);if(o.step==PoliticalGovernanceAgencyAuthoredStep::issue)return i->delegate_accepts&&actor==i->delegate_actor_id&&o.director_policy_id==i->delegate_director_policy_id&&kind==political_governance_agency_issue_command?common_success():common_failure("GovernanceAgencyIntentOriginMismatch",o.intent_id);return common_failure("GovernanceAgencyIntentOriginStepUnknown",o.intent_id);}
}
